import json
import os
import sys
from datetime import datetime, timezone
from pathlib import Path

def load_sessions():
    try:
        with open('sessions.json', 'r') as f:
            return json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return None

def is_valid_session(sessions, auth_token):
    if not sessions:
        return None
    for session in sessions:
        if session['token'] == auth_token and session['expires_at'] > datetime.now(timezone.utc).isoformat():
            return session
    return None

def get_username(sessions, auth_token):
    session = is_valid_session(sessions, auth_token)
    return session['username'] if session else 'anonymous'

def log_access(username, granted):
    with open('access.log', 'a') as f:
        f.write(f"{datetime.now(timezone.utc).isoformat()} {username} {'granted' if granted else 'denied'}\n")

def log_error():
    with open('error.log', 'a') as f:
        f.write(f"{datetime.now(timezone.utc).isoformat()} failed to load sessions\n")

def read_template(template_path):
    with open(template_path, 'r') as f:
        return f.read()

def render_template(template, username, role, server_time):
    return template.replace('{{username}}', username).replace('{{role}}', role).replace('{{server_time}}', server_time)

def main():
    sessions = load_sessions()
    if not sessions:
        log_error()
        print("<h1>Service unavailable</h1>")
        sys.exit(0)

    auth_token = os.getenv('AUTH_TOKEN')
    if auth_token:
        session = is_valid_session(sessions, auth_token)
        if session:
            username = session['username']
            role = session['role']
            server_time = datetime.now(timezone.utc).isoformat()
            template = read_template('page.html')
            rendered = render_template(template, username, role, server_time)
            print(rendered)
        else:
            print("<h1>Access denied</h1><form action='/login'><input type='password' name='password'><button type='submit'>Login</button></form>")
    else:
        print("<h1>Access denied</h1><form action='/login'><input type='password' name='password'><button type='submit'>Login</button></form>")

if __name__ == "__main__":
    main()
